void LiveView::ResetStatements() {
  if (mCountStmt) {
    mCountStmt->Finalize();
    mCountStmt = nullptr;
  }
  if (mCountUnreadStmt) {
    mCountUnreadStmt->Finalize();
    mCountUnreadStmt = nullptr;
  }
  if (mSelectStmt) {
    mSelectStmt->Finalize();
    mSelectStmt = nullptr;
  }
  if (mSelectGroupStmt) {
    mSelectGroupStmt->Finalize();
    mSelectGroupStmt = nullptr;
  }

